import React, { useState } from "react";

const TaskList = ({ tasks, setTasks, setArchive }) => {
  const [newTask, setNewTask] = useState("");

  const handleAddTask = (e) => {
    e.preventDefault();
    if (!newTask.trim()) return;
    setTasks([...tasks, { id: Date.now(), text: newTask, done: false }]);
    setNewTask("");
  };

  const toggleDone = (id) => {
    setTasks(
      tasks.map((task) =>
        task.id === id ? { ...task, done: !task.done } : task
      )
    );
  };

  const handleDelete = (id) => {
    setArchive((prev) => [...prev, tasks.find((t) => t.id === id)]);
    setTasks(tasks.filter((task) => task.id !== id));
  };

  return (
    <section>
      <form onSubmit={handleAddTask} className="flex gap-2 mb-4">
        <input
          type="text"
          className="flex-1 p-2 rounded border"
          placeholder="Dodaj zadanie..."
          value={newTask}
          onChange={(e) => setNewTask(e.target.value)}
        />
        <button className="bg-green-600 text-white px-4 py-2 rounded">
          Dodaj
        </button>
      </form>
      <ul className="space-y-2">
        {tasks.length === 0 && (
          <li className="text-gray-500 italic">Brak zadań – czas na kawę?</li>
        )}
        {tasks.map((task) => (
          <li
            key={task.id}
            className={`flex items-center justify-between bg-white dark:bg-zinc-800 rounded p-2 shadow-sm ${
              task.done ? "opacity-60 line-through" : ""
            }`}
          >
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={task.done}
                onChange={() => toggleDone(task.id)}
                className="accent-green-500"
              />
              <span>{task.text}</span>
            </div>
            <button
              className="text-xs text-red-600 hover:underline"
              onClick={() => handleDelete(task.id)}
            >
              Archiwizuj
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
};

export default TaskList;
